import { Component, OnInit } from '@angular/core';
import { Invoice, InvoiceService, BookingOption } from '../services/invoice.service';

@Component({
  selector: 'app-invoices',
  templateUrl: './invoices.component.html',
  styleUrls: ['./invoices.component.css']
})
export class InvoicesComponent implements OnInit {
  invoices: Invoice[] = [];
  bookingOptions: BookingOption[] = [];
  searchTerm = '';
  isLoading = true;
  errorMessage = '';

  showForm = false;
  editingId: number | null = null;
  formModel: Invoice = this.emptyInvoice();

  constructor(private invoiceService: InvoiceService) {}

  ngOnInit(): void {
    this.loadInvoices();
    this.loadBookingOptions();
  }

  emptyInvoice(): Invoice {
    return {
      BookingId: 0,
      InvoiceNumber: '',
      InvoiceDate: new Date().toISOString().substring(0, 10),
      Amount: 0,
      PaymentStatus: 'Unpaid'
    };
  }

  loadInvoices(): void {
    this.isLoading = true;
    this.invoiceService.getAll(this.searchTerm).subscribe({
      next: (data) => { this.invoices = data; this.isLoading = false; },
      error: (err) => {
        this.errorMessage = err.error?.message || 'Could not load invoices.';
        this.isLoading = false;
      }
    });
  }

  loadBookingOptions(): void {
    this.invoiceService.getBookingOptions().subscribe({
      next: (data) => { this.bookingOptions = data; },
      error: () => { /* non-critical - the form will just show an empty dropdown */ }
    });
  }

  onSearch(): void {
    this.loadInvoices();
  }

  openAddForm(): void {
    this.editingId = null;
    this.formModel = this.emptyInvoice();
    this.showForm = true;
  }

  openEditForm(invoice: Invoice): void {
    this.editingId = invoice.InvoiceId!;
    this.formModel = { ...invoice, InvoiceDate: invoice.InvoiceDate.substring(0, 10) };
    this.showForm = true;
  }

  cancelForm(): void {
    this.showForm = false;
  }

  saveInvoice(): void {
    this.errorMessage = '';

    if (!this.formModel.BookingId) {
      this.errorMessage = 'Please choose which booking this invoice belongs to.';
      return;
    }

    const request = this.editingId
      ? this.invoiceService.update(this.editingId, this.formModel)
      : this.invoiceService.create(this.formModel);

    request.subscribe({
      next: () => {
        this.showForm = false;
        this.loadInvoices();
      },
      error: (err) => {
        this.errorMessage = err.error?.message || 'Could not save invoice.';
      }
    });
  }

  deleteInvoice(invoice: Invoice): void {
    const confirmed = window.confirm(`Delete invoice "${invoice.InvoiceNumber}"?`);
    if (!confirmed) return;

    this.invoiceService.delete(invoice.InvoiceId!).subscribe({
      next: () => this.loadInvoices(),
      error: (err) => {
        this.errorMessage = err.error?.message || 'Could not delete invoice.';
      }
    });
  }
}
<div class="page-header">
  <div>
    <h1>Invoices</h1>
    <p>Bills raised against each booking, and their payment status.</p>
  </div>
  <button class="btn btn-primary" (click)="openAddForm()">+ New invoice</button>
</div>

<div class="search-bar" style="margin-bottom: 18px;">
  <input
    type="text"
    placeholder="Search by invoice #, client, or status..."
    [(ngModel)]="searchTerm"
    (keyup.enter)="onSearch()"
  />
</div>

<p *ngIf="errorMessage" class="error-text">{{ errorMessage }}</p>
<p *ngIf="isLoading">Loading invoices...</p>

<div class="card" *ngIf="!isLoading">
  <table>
    <thead>
      <tr>
        <th>Invoice #</th>
        <th>Client</th>
        <th>Campaign</th>
        <th>Date</th>
        <th>Amount</th>
        <th>Payment</th>
        <th></th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let inv of invoices">
        <td>{{ inv.InvoiceNumber }}</td>
        <td>{{ inv.ClientName }}</td>
        <td>{{ inv.Campaign }}</td>
        <td>{{ inv.InvoiceDate | date: 'mediumDate' }}</td>
        <td>₹{{ inv.Amount | number }}</td>
        <td><span class="badge" [ngClass]="'badge-' + inv.PaymentStatus.toLowerCase()">{{ inv.PaymentStatus }}</span></td>
        <td class="actions">
          <button class="btn btn-outline" (click)="openEditForm(inv)">Edit</button>
          <button class="btn btn-danger" (click)="deleteInvoice(inv)">Delete</button>
        </td>
      </tr>
      <tr *ngIf="invoices.length === 0">
        <td colspan="7">No invoices found.</td>
      </tr>
    </tbody>
  </table>
</div>

<!-- Add / Edit modal -->
<div class="modal-backdrop" *ngIf="showForm" (click)="cancelForm()">
  <div class="modal-card" (click)="$event.stopPropagation()">
    <h3>{{ editingId ? 'Edit invoice' : 'New invoice' }}</h3>

    <form (ngSubmit)="saveInvoice()">
      <label>Booking</label>
      <select [(ngModel)]="formModel.BookingId" name="bookingId">
        <option [value]="0" disabled>Select a booking...</option>
        <option *ngFor="let b of bookingOptions" [value]="b.BookingId">
          {{ b.ClientName }} — {{ b.Campaign }}
        </option>
      </select>

      <label>Invoice number</label>
      <input type="text" [(ngModel)]="formModel.InvoiceNumber" name="invoiceNumber" placeholder="INV-1004" required />

      <label>Invoice date</label>
      <input type="date" [(ngModel)]="formModel.InvoiceDate" name="invoiceDate" required />

      <label>Amount (₹)</label>
      <input type="number" [(ngModel)]="formModel.Amount" name="amount" min="0" required />

      <label>Payment status</label>
      <select [(ngModel)]="formModel.PaymentStatus" name="paymentStatus">
        <option value="Unpaid">Unpaid</option>
        <option value="Paid">Paid</option>
        <option value="Overdue">Overdue</option>
      </select>

      <div class="modal-actions">
        <button type="button" class="btn btn-outline" (click)="cancelForm()">Cancel</button>
        <button type="submit" class="btn btn-primary">Save invoice</button>
      </div>
    </form>
  </div>
</div>
